import{z as n,x as o,o as e,c as l,q as A,j as t,D as a,d as r,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"嵌入式案例与收束","description":"","frontmatter":{"title":"嵌入式案例与收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-case-map.md","filePath":"cs/emb-case-map.md","lastUpdated":1791413859000}'),C={name:"cs/emb-case-map.md"};function m(p,E,d,c,D,h){const B=o("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="嵌入式案例与收束" tabindex="-1">嵌入式案例与收束 <a class="header-anchor" href="#嵌入式案例与收束" aria-label="Permalink to &quot;嵌入式案例与收束&quot;">​</a></h1><div class="epigraph"><p>读完一门课该带走的不是寄存器名，而是几张跨芯片成立的骨架：所有预算按最坏情况记账，所有信任从独立域出发，所有承诺都要留下可核查的证据。</p><footer>—— 据Barry, Mastering the FreeRTOS Real Time Kernel；NIST SP 800-193；本课程九课口径整理</footer></div><p><a href="/cs/emb-testing-simulation">上一课</a>给了把整个体系钉在质量上的测试分层。本课程到此收束：本课把九课拼回一张图——一台电池供电的冷链温度记录仪从上电、服役五年到退网的完整生命周期——并把这层实践沉淀出的共同原理收在三条骨架上，给主干课的通用原理补上「落在一颗 MCU 上是什么样」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的是：换一颗芯片、换一个 RTOS、换一条总线时，哪些知识跟着版本走、哪些不跟。不这么做会错在哪：把 STM32 的寄存器名与厂商库函数当知识带走，换到 RISC-V 平台全部作废；把「能跑」当「做完了」，忽略这台设备要无人值守五年——五年里的每一次断电、每一块电池衰减、每一次固件升级，都是设计时就要还的账。收束把九课的对象各归一条时间线，看它们在生命周期里何时出场、向谁要证据。</p><p><span class="marginnote">直觉类比：收束像毕业答辩——不考「背出哪个寄存器」，而考「换一台风没见过的机器你还会什么」。寄存器名是各家的方言，预算、信任、证据这三件事是普通话：方言到了新平台作废，普通话照用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>案例按生命周期走。出厂前：<a href="/cs/emb-bare-metal-boot">裸机启动</a>的向量表与段搬运烧进闪存；调试口上锁、根公钥写入 OTP，信任链封顶（<a href="/cs/emb-security">嵌入式安全</a>）。服役期每三十秒一个循环：定时器唤醒（<a href="/cs/emb-power-management">功耗管理</a>的占空比账，平均电流压在 25 µA 内）；<a href="/cs/emb-i2c-spi">I2C 与 SPI</a> 上读传感器、写记录；<a href="/cs/emb-rtos">实时操作系统</a>里三个任务按周期域调度，采样任务最短周期优先级最高；每轮循环末核对任务心跳再喂狗（<a href="/cs/emb-watchdog-failsafe">看门狗与失效安全</a>）。每年几次：OTA 下发新固件写备槽，试运行确认后才转正（<a href="/cs/emb-ota-updates">OTA 更新</a>）。整个研发生命周期：单元测试、仿真回归、HIL 故障注入、现场遥测四层接力（<a href="/cs/emb-testing-simulation">测试与仿真</a>）。中断与事件是这条线的纵轴——每一次唤醒都走<a href="/cs/emb-interrupt-practice">中断实践</a>立下的纪律。</p>',8)),(e(),t(i,null,{default:a(()=>[s(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FACT%5B%22%E5%87%BA%E5%8E%82%EF%BC%9A%E7%83%A7%E5%BD%95%E3%80%81%E9%94%81%E8%B0%83%E8%AF%95%E5%8F%A3%E3%80%81OTP%20%E5%86%99%E6%A0%B9%E5%85%AC%E9%92%A5%22%5D%20--%3E%20CYC%5B%22%E6%9C%8D%E5%BD%B9%E5%BE%AA%E7%8E%AF%EF%BC%9A%E5%94%A4%E9%86%92%E3%80%81%E9%87%87%E6%A0%B7%E3%80%81%E8%AE%B0%E5%BD%95%E3%80%81%E5%96%82%E7%8B%97%E3%80%81%E6%B7%B1%E7%9D%A1%22%5D%0A%20%20CYC%20--%3E%7C%22%E6%AF%8F%E5%B9%B4%E5%87%A0%E6%AC%A1%22%7C%20OTA%5B%22OTA%EF%BC%9A%E5%A4%87%E6%A7%BD%E5%86%99%E5%85%A5%E3%80%81%E8%AF%95%E8%BF%90%E8%A1%8C%E3%80%81%E7%A1%AE%E8%AE%A4%E6%88%96%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20OTA%20--%3E%20CYC%0A%20%20CYC%20--%3E%7C%22%E5%BC%82%E5%B8%B8%22%7C%20FAIL%5B%22%E7%9C%8B%E9%97%A8%E7%8B%97%E5%A4%8D%E4%BD%8D%EF%BC%9A%E5%AE%89%E5%85%A8%E7%8A%B6%E6%80%81%E5%8A%A0%E5%A4%B1%E6%95%88%E6%97%A5%E5%BF%97%22%5D%0A%20%20FAIL%20--%3E%20CYC%0A%20%20CYC%20--%3E%7C%22%E4%BA%94%E5%B9%B4%22%7C%20RET%5B%22%E9%80%80%E7%BD%91%EF%BC%9A%E9%94%80%E6%AF%81%E5%AF%86%E9%92%A5%EF%BC%8C%E5%8F%AA%E7%95%99%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p><span class="marginnote">这台记录仪的五年账本：220 mAh 电池按 25 µA 平均电流算余量；闪存按每日几十次记录加每年一两次 OTA 算擦写次数，五年约几千次，低于一万次的器件上限但余量不足一倍——预算不做满，是收束阶段最常补的一课。</span></p><p><span class="marginnote">数字实例：220 mAh ÷ 25 µA ≈ 8800 小时，只够一年。要撑五年，平均电流得再压到 5 µA 上下，或者换更大的电池——这就是「占空比账」的严苛之处：睡眠电流再小，唤醒太频繁，平均电流照样超支。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>九课拼起来后，三条骨架浮出来。第一，<strong>最坏情况记账</strong>：功耗按睡眠电流与唤醒税算平均，实时按最长关中断窗口算延迟，闪存按擦写次数算寿命，失效按最长恢复路径算可用性——没有一个预算用平均值交卷。第二，<strong>独立域与单点控制</strong>：看门狗的时钟域独立于软件死活，启动裁决由引导加载器单点执掌，信任链从不可改写的 OTP 出发——凡是「最后说了算」的东西，都必须住在别的东西碰不到的地方。第三，<strong>承诺要变成证据</strong>：喂狗前查心跳，接受固件前写确认位，出厂前故障注入踩一遍失效梯子——没有证据的承诺，等于没有承诺。这三条不随芯片换、不随 RTOS 换，是本课程的「知识里不跟版本走」的那部分。</p><p><span class="marginnote">常见误区：把「加了个看门狗」当失效安全。喂狗代码若和业务混在同一片软件里，业务死了可能没人喂狗——也可能更糟：某个定时器把狗喂得忘了主任务已死。独立域要求看门狗用自己的时钟、自己的喂狗窗口，让崩溃能被它察觉，而不是被它掩护。</span></p><p>三条骨架各自落到哪些具体机制上？</p>',6)),(e(),t(i,null,{default:a(()=>[s(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E9%AA%A8%E6%9E%B6%E4%B8%80%EF%BC%9A%E6%9C%80%E5%9D%8F%E6%83%85%E5%86%B5%E8%AE%B0%E8%B4%A6%22%5D%20--%3E%20E1%5B%22%E5%8A%9F%E8%80%97%E6%8C%89%E7%9D%A1%E7%9C%A0%E7%94%B5%E6%B5%81%E5%8A%A0%E5%94%A4%E9%86%92%E7%A8%8E%22%5D%0A%20%20S1%20--%3E%20E2%5B%22%E5%AE%9E%E6%97%B6%E6%8C%89%E6%9C%80%E9%95%BF%E5%85%B3%E4%B8%AD%E6%96%AD%E7%AA%97%E5%8F%A3%22%5D%0A%20%20S1%20--%3E%20E3%5B%22%E9%97%AA%E5%AD%98%E6%8C%89%E6%93%A6%E5%86%99%E6%AC%A1%E6%95%B0%E7%AE%97%E5%AF%BF%E5%91%BD%22%5D%0A%20%20S2%5B%22%E9%AA%A8%E6%9E%B6%E4%BA%8C%EF%BC%9A%E7%8B%AC%E7%AB%8B%E5%9F%9F%E4%B8%8E%E5%8D%95%E7%82%B9%E6%8E%A7%E5%88%B6%22%5D%20--%3E%20E4%5B%22%E7%9C%8B%E9%97%A8%E7%8B%97%E6%97%B6%E9%92%9F%E7%8B%AC%E7%AB%8B%E4%BA%8E%E8%BD%AF%E4%BB%B6%22%5D%0A%20%20S2%20--%3E%20E5%5B%22%E4%BF%A1%E4%BB%BB%E9%93%BE%E4%BB%8E%20OTP%20%E5%87%BA%E5%8F%91%22%5D%0A%20%20S3%5B%22%E9%AA%A8%E6%9E%B6%E4%B8%89%EF%BC%9A%E6%89%BF%E8%AF%BA%E5%8F%98%E6%88%90%E8%AF%81%E6%8D%AE%22%5D%20--%3E%20E6%5B%22%E5%96%82%E7%8B%97%E5%89%8D%E5%85%88%E6%9F%A5%E4%BB%BB%E5%8A%A1%E5%BF%83%E8%B7%B3%22%5D%0A%20%20S3%20--%3E%20E7%5B%22%E6%94%B6%E5%9B%BA%E4%BB%B6%E5%89%8D%E5%86%99%E7%A1%AE%E8%AE%A4%E4%BD%8D%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不替代三样东西。芯片手册与厂商勘误表：寄存器级的真值只认手册，本课程给的是组织它们的方式。无线与认证：射频协议栈、安规与 EMC 是各自独立的深水区，本课程只在功耗与测试的接口处与之相接。更高等级的安全与实时：双通道表决、WCET 证明、功能安全认证属于另一套论证体系，单点失效的工程兜底只是它的起点。若产品的需求长出屏幕、浏览器与人机交互，该换 Linux 级的硬件栈重新开始——那是主干课操作系统与固件世界的分界，本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>九课拼成一台设备的生命周期：出厂封信任链，服役循环里功耗、实时、看门狗各司其职。</li><li>三条骨架跨平台成立：最坏情况记账、独立域与单点控制、承诺变成证据。</li><li>预算不做满：电池、擦写、实时余量都要留出一倍以上，收束阶段专查这件事。</li><li>换芯片带走的是骨架不是寄存器名；手册与勘误表永远是最终权威。</li><li>出处：Barry, <em>Mastering the FreeRTOS Real Time Kernel</em>；NIST SP 800-193；据本课程九课的对象账与骨架口径整理。</li></ul>',4))])}const _=n(C,[["render",m]]);export{F as __pageData,_ as default};
